page(HF_PATH,'Class 40 · Healthy Food & Eating Well — 21 Printable Food-Habit Cards (Ages 4–5)','Twenty-one printable food cards for ages 4–5 in three shelves — what’s on the plate, meals & drinks, and how we eat — every card wearing one big habit a child can say back: the balanced plate, eat a rainbow, try new foods, wash your hands first. Each card has its own short page with one thing to try at tonight’s table, starting from the smiling cover apple.',crumb([['Learning Path','/learning-path/'],['Healthy Food & Eating Well']])+healthyFoodClassBody(),{schema:[ssBc(site,[['Learning Path','/learning-path/'],['Healthy Food & Eating Well',HF_PATH]])],ogImage:HF_BASE+HF_COVER.file,ogAlt:HF_COVER.alt,ogW:HF_COVER.w,ogH:HF_COVER.h});
