page('/toddler/2-years/school-garden/','School Garden for Toddlers — Garden Collections','Garden collections for 2-year-olds: name the flowers and the things in the garden, then meet garden bugs and garden animals with picture cards, gentle games and quiet nature hunts.',crumb([['Toddler','/toddler/'],['Age 2','/toddler/2-years/'],['School Garden']])+heading('THE SCHOOL GARDEN','School Garden','The outside part of the school — name the flowers, the things and the little creatures that live around gardens and the great outdoors.')+`<section class="wrap section compact"><div class="fc-stages"><a class="fc-stage lesson-card-link" href="/toddler/2-years/garden-bugs-and-friends/"><div class="fc-stage-pills"><span class="fc-age">Garden collection</span><span class="fc-class">Nature &amp; Talk</span></div><h3>Bugs &amp; Insects</h3><p>Twenty little garden friends — a bee, a butterfly, a snail and more — with two gentle games and a garden hunt for after class.</p><span class="fc-open">Open Bugs &amp; Insects <span aria-hidden="true">↗</span></span></a><a class="fc-stage lesson-card-link" href="${gfLesson.path}"><div class="fc-stage-pills"><span class="fc-age">Garden collection</span><span class="fc-class">Nature &amp; Talk</span></div><h3>Garden Animals &amp; Friends</h3><p>${gfLesson.hubBlurb}</p><span class="fc-open">Open Garden Animals &amp; Friends <span aria-hidden="true">↗</span></span></a><a class="fc-stage lesson-card-link" href="${gflLesson.path}"><div class="fc-stage-pills"><span class="fc-age">Garden collection</span><span class="fc-class">Nature &amp; Talk</span></div><h3>Garden Flowers</h3><p>${gflLesson.hubBlurb}</p><span class="fc-open">Open Garden Flowers <span aria-hidden="true">↗</span></span></a><a class="fc-stage lesson-card-link" href="${gthLesson.path}"><div class="fc-stage-pills"><span class="fc-age">Garden collection</span><span class="fc-class">Nature &amp; Talk</span></div><h3>Garden Things</h3><p>${gthLesson.hubBlurb}</p><span class="fc-open">Open Garden Things <span aria-hidden="true">↗</span></span></a></div><p class="lesson-note">Every collection here is complete and ready to play — the garden keeps growing when new ones are finished.</p></section>`,{schema:[{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[['Home','/'],['Toddler','/toddler/'],['Age 2','/toddler/2-years/'],['School Garden','/toddler/2-years/school-garden/']].map(([name,path],i)=>({'@type':'ListItem',position:i+1,name,item:site+path}))}]});
page('/toddler/2-years/circle-time/','Circle Time for 2-Year-Olds','Short circle time activities for 2-year-olds at home: a hello rhythm, copy-me movement, listening games, faces, a tiny story and goodbye — parent-led, in about five minutes.',crumb([['Toddler','/toddler/'],['Age 2','/toddler/2-years/'],['Circle Time']])+heading('CIRCLE TIME · AGE 2','Circle Time','The rug is ready — sit down together and start with a hello.')+circleTimeHubBody(helloSchool),{schema:[{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[['Home','/'],['Toddler','/toddler/'],['Age 2','/toddler/2-years/'],['Circle Time','/toddler/2-years/circle-time/']].map(([name,path],i)=>({'@type':'ListItem',position:i+1,name,item:site+path}))}]});
