page('/art-wall/','Our Art Wall: classroom art on display','A preschool-style art wall for Kiddo School: eleven classroom example drawings — a family, a rainbow, a cat, a house, a dinosaur, flowers, a car, a happy face, fish under the sea, shapes and a butterfly — pinned up to enjoy together.',crumb([['My Classroom','/my-classroom/'],['Our Art Wall']])+heading('THE CLASSROOM WALL','Our Art Wall','Every preschool has a wall where the drawings go. This one is ours: pin something up, step back and smile at it — then go make something of your own for the wall at home.')+artWallBody(),{schema:[{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[['Home','/'],['My Classroom','/my-classroom/'],['Our Art Wall','/art-wall/']].map(([name,path],i)=>({'@type':'ListItem',position:i+1,name,item:site+path}))}],ogImage:artWallOgImage,ogAlt:artWallOgAlt});
page('/school-calendar/','School Calendar','A gentle weekly rhythm for Kiddo School: one small, real idea for each day of the week — a class on Monday, Circle Time on Wednesday, the library on Saturday — picked up whenever you are ready.',crumb([['My Classroom','/my-classroom/'],['School Calendar']])+heading('THE SCHOOL WEEK','School Calendar','One small idea for each day of the week. Everything here is already on the school shelves — the calendar just arranges it into a gentle rhythm your family can follow, at your own pace.')+schoolCalendarBody(),{schema:[{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[['Home','/'],['My Classroom','/my-classroom/'],['School Calendar','/school-calendar/']].map(([name,path],i)=>({'@type':'ListItem',position:i+1,name,item:site+path}))}]});
page('/principals-office/','The Principal’s Office','A quiet room where parents and grown-ups can write to the Principal of Kiddo School — questions, requests, feedback, suggestions, complaints or a technical problem. Read by the Principal only.',crumb([['My Classroom','/my-classroom/'],['Principal’s Office']])+heading('KNOCK KNOCK','The Principal’s Office','A quiet little room behind the classroom. Grown-ups can write to the Principal here — a question, a request, some feedback, a suggestion, a complaint or a technical problem.')+principalOfficeBody(),{schema:[{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[['Home','/'],['My Classroom','/my-classroom/'],['Principal’s Office','/principals-office/']].map(([name,path],i)=>({'@type':'ListItem',position:i+1,name,item:site+path}))}]});
page('/school-community/','Our School Community','See what families are making, learning and sharing at Kiddo School: the Art Wall, the Sticky Note Wall and honest family reviews — everything reviewed by the school office first.',crumb([['School Community']])+heading('TOGETHER AT KIDDO SCHOOL','Our School Community','See what families are making, learning and sharing at Kiddo School.')+schoolCommunityBody(),{schema:[{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[['Home','/'],['School Community','/school-community/']].map(([name,path],i)=>({'@type':'ListItem',position:i+1,name,item:site+path}))}]});
page(WW_PATH,'Who Works at My School? — The People Who Help at School','Many people help your school run every day: the teacher, the librarian, the school nurse, the crossing guard and more. Sixteen friendly person cards in three groups — who teaches, who helps, who keeps us safe — with the principal’s door opening straight into the Principal’s Office.',crumb([['School Community','/school-community/'],['Who Works at My School']])+heading('SCHOOL COMMUNITY · THE PEOPLE','Who works at my school?','Many people help your school run every day.')+whoWorksBody(),{schema:[{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[['Home','/'],['School Community','/school-community/'],['Who Works at My School',WW_PATH]].map(([name,path],i)=>({'@type':'ListItem',position:i+1,name,item:site+path}))}],ogImage:WW_BASE+'cover.webp',ogW:1000,ogH:707,ogAlt:'Cover of the Who Works at My School set from Kiddo School: the words “School People Flashcards” over six school people — a teacher, a crossing guard, the school nurse, the principal, a cafeteria worker and the janitor.'});
