const wsImageCache=new Map();
function storyImage(w){
 const href=w.ws.imgHref;
 if(!wsImageCache.has(href)){
  const data=readFileSync('public'+href);
  const jpg=data; // JPEG bytes pass straight into the PDF (DCTDecode)
  wsImageCache.set(href,{data:jpg,w:Math.round(1400),h:Math.round(1400*(w.ws.ar))});
 }
 return wsImageCache.get(href);
}
