/* Homepage: fetch the hero picture at the very start (it is the largest contentful paint). The preload carries the same srcset/sizes as the <img> so mobile preloads the 880w file, never a double download. */
{
 let h=readFileSync('dist/index.html','utf8');
 const hero=h.match(/<img src="([^"]*kiddo-homepage-hero\.webp[^"]*)" srcset="([^"]*)" sizes="([^"]*)"/);
 if(hero&&!h.includes('rel="preload" as="image"'))writeFileSync('dist/index.html',h.replace('<meta name="viewport"','<link rel="preload" as="image" href="'+hero[1]+'" imagesrcset="'+hero[2]+'" imagesizes="'+hero[3]+'" fetchpriority="high"><meta name="viewport"'));
}
/* Breadcrumb structured data for every page whose visible breadcrumb has no BreadcrumbList yet:
   derived from the on-page <nav class="breadcrumbs">, so markup and schema can never disagree. */
{
 const walk=d=>readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(d+'/'+e.name):[d+'/'+e.name]);
 const unesc=t=>t.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'");
 for(const f of walk('dist').filter(f=>f.endsWith('.html')&&f!=='dist/404.html')){
  let h=readFileSync(f,'utf8');
  if(h.includes('BreadcrumbList'))continue;
  const nav=h.match(/<nav class="breadcrumbs[^"]*" aria-label="Breadcrumb">([\s\S]*?)<\/nav>/);
  const can=h.match(/<link rel="canonical" href="([^"]+)"/);
  if(!nav||!can)continue;
  const items=[...nav[1].matchAll(/<a href="([^"]+)">([^<]+)<\/a>|<span aria-current="page">([^<]+)<\/span>/g)].map(m=>m[1]?{name:unesc(m[2]),item:site+m[1]}:{name:unesc(m[3]),item:can[1]});
  if(items.length<2)continue;
  const ld={'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:items.map((x,i)=>({'@type':'ListItem',position:i+1,name:x.name,item:x.item}))};
  h=h.replace('</head>','<script type="application/ld+json">'+JSON.stringify([ld]).replace(/</g,'\\u003c')+'</script></head>');
  writeFileSync(f,h);
 }
}
writeFileSync('dist/sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">${allRoutes.map(p=>routeImg.has(p)?`<url><loc>${site+p}</loc><image:image><image:loc>${e(routeImg.get(p))}</image:loc></image:image></url>`:`<url><loc>${site+p}</loc></url>`).join('')}</urlset>\n`);
